using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.WoodSorrel;

/// <summary>
/// Wood sorrel, clover-like leaves and white flowers veined with pink in the damp shade of the Mistlands. Model:
/// generated by AssetSource/Tools/make_forage_models.py. Magecaps picked in the Mistlands can also give it.
/// </summary>
public class WoodSorrel : ForageableBase
{
    /// <summary>
    /// Prefab name of the wood sorrel item.
    /// </summary>
    public const string PrefabName = "WhiteHiltWoodSorrel";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Wood Sorrel";

    /// <inheritdoc/>
    protected override string Description => "Small leaves folded like hearts, sharp and sour as an apple. They wake up a sausage and freshen a mead.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Thistle";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 2,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 3f,
        MinAltitude = 1f,
        MaxTilt = 30f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => "Pickable_Mushroom_Magecap";

    /// <inheritdoc/>
    protected override float ExtraDropChance => 0.2f;

    /// <inheritdoc/>
    protected override float DefaultGroundClearance => 0.1f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, "woodsorrel", 0.11f);
    }
}
